const audio = { music:(function(){try{var t=window.top;if(t!==window&&t.PortalMusic)return t.PortalMusic.proxy;}catch(e){}return null;})()||new Audio('/assets/audio/musica-portal.mp3'), tap:PMS('assets/audio/toque-luminoso.mp3'), reveal:PMS('assets/audio/revelacion-astral.mp3') };
audio.music.loop = true;
const clamp = (v,min,max) => Math.max(min, Math.min(max,v));
audio.music.volume = clamp(.16,0,1); audio.tap.volume = clamp(.25,0,1); audio.reveal.volume = clamp(.32,0,1);
let audioStarted = false;

function log(name,data={}) { window.ProgressLogger?.logProgress(name,data); }
function unlockAudio() { if(audioStarted || state.muted) return; audioStarted=true; audio.music.play().catch(()=>{audioStarted=false;}); }
function sound(kind='tap') { unlockAudio(); if(state.muted) return; const clip=audio[kind]; clip.currentTime=0; clip.play().catch(()=>{}); }
function stableHash(value) { let h=2166136261; for(const c of value) { h ^= c.charCodeAt(0); h=Math.imul(h,16777619); } return Math.abs(h>>>0); }
function shuffle(list,seed=17) { return list.slice().sort((a,b)=>((stableHash(a.id+seed)-stableHash(b.id+seed)))); }
function moduleLabel(module) { return module==='aura'?'Color del aura':module==='soul'?'Edad del alma':module==='star'?'Origen estelar':'Vidas pasadas'; }
function activeQuestions() {
  const sets = state.mode==='aura'?[auraQuestions] : state.mode==='soul'?[soulQuestions] : state.mode==='star'?[starQuestions] : state.mode==='past'?[pastQuestions] : [auraQuestions,soulQuestions,starQuestions,pastQuestions];
  return sets.flatMap(set => shuffle(set, 29));
}
function layout(content) {
  mount.innerHTML = `<div class="app"><header class="topbar"><button class="brand brand-button ${state.screen==='welcome'?'topbar-brand-hidden':''}" id="home-link" aria-label="Volver al inicio"><span class="brand-name">AURA</span></button><button class="icon-btn" id="sound-toggle" aria-label="${state.muted?'Activar sonido':'Silenciar sonido'}">${state.muted?'♩':'♫'}</button></header><main>${content}</main></div>`;
  document.querySelector('#sound-toggle')?.addEventListener('click',toggleSound);
  document.querySelector('#home-link')?.addEventListener('click',()=>{stopCamera(); state.screen='welcome'; render();});
}
function toggleSound() { state.muted=!state.muted; localStorage.setItem('lumina-muted',String(state.muted)); if(state.muted) audio.music.pause(); else {audioStarted=false;unlockAudio();sound();} render(); }

function renderWelcome() {
  const hasSaved = state.history.length || localStorage.getItem('lumina-last-report');
  layout(`<section class="screen hero"><div class="hero-brand">AURA</div><p class="eyebrow">Exploración espiritual</p><img class="mandala hero-mandala" src="assets/mandala-aura.webp" alt="Mandala astral decorativo"><p class="subtitle">Descubre el color de aura más afín a tu personalidad, tus sentimientos y la energía que expresas. También puedes explorar arquetipos del alma, afinidades estelares y narrativas de vidas pasadas.</p><div class="notice"><span>☾</span><div><b>Tu lectura comienza aquí:</b> tus respuestas, tu personalidad, tus sentimientos y la tonalidad de tu fotografía se integran para revelar el color de aura más cercano a tu perfil espiritual.</div></div><button class="primary" id="complete">Experiencia completa</button><div class="quick-grid"><button class="quick-card" data-mode="aura"><b>✦</b><span>Descubrir mi color</span><small>42 preguntas</small></button><button class="quick-card" data-mode="soul"><b>◌</b><span>Edad del alma</span><small>24 preguntas</small></button><button class="quick-card" data-mode="past"><b>⌁</b><span>Vidas pasadas</span><small>Exploración narrativa</small></button><button class="quick-card" data-mode="star"><b>✧</b><span>Origen estelar</span><small>Arquetipos simbólicos</small></button></div><div class="home-links">${hasSaved?'<button class="text-button" id="history">Mis resultados</button>':''}<button class="text-button" id="learn">Aprender sobre el modelo</button></div><p class="privacy">La fotografía es opcional. Si la usas, se analiza localmente para diseñar una visualización artística y no se guarda.</p></section>`);
  document.querySelector('#complete').addEventListener('click',()=>startMode('complete'));
  document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>startMode(btn.dataset.mode)));
  document.querySelector('#history')?.addEventListener('click',renderHistory);
  document.querySelector('#learn')?.addEventListener('click',renderLearn);
}
function startMode(mode) { sound(); state.mode=mode; state.questions=activeQuestions(); state.questionIndex=0; state.answers={}; state.meta={}; state.photo=null; state.report=null; state.screen='survey'; log('modulo_iniciado',{mode}); render(); }
function renderSurvey() {
  const q=state.questions[state.questionIndex]; const answer=state.answers[q.id]||0; const total=state.questions.length;
  layout(`<section class="screen survey-screen"><div class="progress-row"><div class="progress-meta"><span>${moduleLabel(q.module).toUpperCase()}</span><span>${state.questionIndex+1} / ${total}</span></div><div class="progress"><i style="width:${((state.questionIndex+1)/total)*100}%"></i></div></div><div class="question"><p class="eyebrow">${q.id}</p><h2>${q.text}</h2><p>Responde pensando en cómo eres generalmente, no solo en un día concreto.</p></div><div class="scale-options">${SCALE.map(([value,label])=>`<button class="scale-option ${answer===Number(value)?'selected':''}" data-value="${value}"><span>${value}</span><em>${label}</em></button>`).join('')}</div><div class="nav-row"><button class="secondary" id="back">←</button><button class="primary" id="next" ${answer?'':'disabled'}>${state.questionIndex===total-1?'Continuar':'Siguiente'}</button></div><p class="survey-note">Escala 1–5 · tus respuestas solo se usan para esta lectura local.</p></section>`);
  document.querySelectorAll('[data-value]').forEach(btn=>btn.addEventListener('click',()=>{state.answers[q.id]=Number(btn.dataset.value);sound();renderSurvey();}));
  document.querySelector('#back').addEventListener('click',()=>{sound();if(state.questionIndex===0){state.screen='welcome';render();}else{state.questionIndex--;render();}});
  document.querySelector('#next').addEventListener('click',()=>{sound();if(state.questionIndex<total-1){state.questionIndex++;render();}else{state.screen='context';render();}});
}
function renderContext() {
  const isPast = ['past','complete'].includes(state.mode);
  if(!isPast) return renderPhoto();
  layout(`<section class="screen card context-card"><p class="eyebrow">Matices opcionales</p><h2>¿Qué resonó contigo?</h2><p class="subtitle">Estas selecciones afinan la narrativa cultural del módulo de vidas pasadas. Omitirlas no reduce tu lectura.</p><label>Época o cultura que sientes cercana<select id="historical">${HISTORICAL.map((v,i)=>`<option value="${i}" ${state.meta.historical===i?'selected':''}>${v}</option>`).join('')}</select></label><label>Región con la que sientes afinidad<select id="geographic">${GEOGRAPHIC.map((v,i)=>`<option value="${i}" ${state.meta.geographic===i?'selected':''}>${v}</option>`).join('')}</select></label><div class="notice"><span>⌁</span><div>Una afinidad cultural o geográfica reportada no confirma una vida anterior. Puede surgir de intereses, recuerdos, educación o imaginación.</div></div><button class="primary" id="context-next">Continuar</button><button class="secondary" id="context-back">Volver</button></section>`);
  document.querySelector('#context-next').addEventListener('click',()=>{state.meta.historical=Number(document.querySelector('#historical').value);state.meta.geographic=Number(document.querySelector('#geographic').value);sound();renderPhoto();});
  document.querySelector('#context-back').addEventListener('click',()=>{sound();state.questionIndex=state.questions.length-1;state.screen='survey';render();});
}
function renderPhoto() {
  const auraPhoto = state.mode === 'aura';
  const photoInstruction = auraPhoto
    ? 'Para esta lectura, toma o carga una foto de frente con fondo blanco uniforme y buena luz. La imagen se usará para calcular un color visual simbólico y dibujar un halo alrededor de tu retrato.'
    : 'Puedes continuar sin foto. Si la añades, solo observaremos luz y color general para estilizar el gráfico; la cámara no detecta un campo espiritual.';
  const placeholder = auraPhoto
    ? '<div class="photo-placeholder"><div><span class="photo-icon">◯</span>Rostro al frente · fondo blanco<br><small>La foto es necesaria para analizar el color visual</small></div></div>'
    : '<div class="photo-placeholder"><div><span class="photo-icon">◯</span>Rostro al frente · pared clara<br><small>La foto es opcional</small></div></div>';
  const sectionClass = auraPhoto ? 'screen card photo-zone photo-required' : 'screen card photo-zone';
  const buttonLabel = state.photo ? (auraPhoto ? 'Analizar foto y crear aura' : 'Crear visualización') : (auraPhoto ? 'Añade una foto para continuar' : 'Continuar sin fotografía');
  layout(`<section class="${sectionClass}"><p class="eyebrow">${auraPhoto ? 'Foto necesaria para el color del aura' : 'Visualización opcional'}</p><h2>${auraPhoto ? 'Fotografía con fondo blanco' : 'Da forma a tu halo'}</h2><p class="subtitle">${photoInstruction}</p><div class="photo-frame" id="photo-frame">${state.photo?`<img src="${state.photo}" alt="Fotografía seleccionada">`:placeholder}</div><div class="photo-actions"><button class="secondary" id="camera" style="margin:0">Usar cámara</button><label class="file-label">Cargar foto<input id="file" type="file" accept="image/*" capture="user"></label></div><div class="notice"><span>⌁</span><div><b>${auraPhoto ? 'Cómo se interpreta:' : 'Privacidad:'}</b> ${auraPhoto ? 'el fondo blanco ayuda a separar zonas muy claras de los colores presentes en la imagen. Esta tonalidad se combina con tu personalidad y tus sentimientos para definir el color de aura más afín a tu perfil.' : 'la imagen se mantiene en memoria durante la lectura, no se sube a un servidor y no se incluye en el historial guardado.'}</div></div><button class="primary" id="read" ${auraPhoto && !state.photo ? 'disabled' : ''}>${buttonLabel}</button><button class="secondary" id="photo-back">Volver</button></section>`);
  document.querySelector('#file').addEventListener('change',handleFile); document.querySelector('#camera').addEventListener('click',startCamera); document.querySelector('#read').addEventListener('click',beginAnalysis); document.querySelector('#photo-back').addEventListener('click',()=>{stopCamera();sound();state.screen=(state.mode==='past'||state.mode==='complete')?'context':'survey';render();});
}
async function startCamera() {
  sound(); if(!navigator.mediaDevices?.getUserMedia) return toast('Esta cámara no está disponible. Puedes cargar una foto.');
  try { stopCamera(); state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false}); const frame=document.querySelector('#photo-frame');frame.innerHTML='<video autoplay playsinline muted></video>';const video=frame.querySelector('video');video.srcObject=state.stream;const button=document.querySelector('#camera');button.textContent='Tomar foto';button.replaceWith(button.cloneNode(true));document.querySelector('#camera').addEventListener('click',()=>capturePhoto(video)); } catch { toast('No se pudo abrir la cámara. Puedes cargar una fotografía.'); }
}
function capturePhoto(video) { const canvas=document.createElement('canvas');canvas.width=video.videoWidth||480;canvas.height=video.videoHeight||640;canvas.getContext('2d').drawImage(video,0,0,canvas.width,canvas.height);state.photo=canvas.toDataURL('image/jpeg',.84);stopCamera();sound();analyzeImage(state.photo).then(renderPhoto); }
function handleFile(event) { const file=event.target.files?.[0];if(!file||!file.type.startsWith('image/'))return toast('Selecciona un archivo de imagen válido.');if(file.size>12*1024*1024)return toast('La imagen es demasiado grande. Elige una menor de 12 MB.');const reader=new FileReader();reader.onload=()=>{state.photo=reader.result;sound();analyzeImage(state.photo).then(renderPhoto);};reader.readAsDataURL(file); }
function classifyPhotoColor(r,g,b,signalRatio) {
  const max=Math.max(r,g,b), min=Math.min(r,g,b), light=(r+g+b)/765, saturation=max?((max-min)/max):0;
  if(signalRatio<.02 || (saturation<.1 && light>.84)) return {key:'white',confidence:.28};
  if(light<.2) return {key:'black',confidence:clamp(.35+(1-light)*.45,.35,.9)};
  if(saturation<.13) return {key:light>.64?'silver':'gray',confidence:clamp(.3+(1-saturation)*.35,.3,.78)};
  const delta=max-min; let hue=0;
  if(delta) { if(max===r) hue=60*(((g-b)/delta)%6); else if(max===g) hue=60*((b-r)/delta+2); else hue=60*((r-g)/delta+4); }
  if(hue<0) hue+=360;
  let key='violet';
  if(hue<15||hue>=345) key='red'; else if(hue<43) key='orange'; else if(hue<68) key=light>.68?'gold':'yellow'; else if(hue<155) key=saturation>.58?'emerald':'green'; else if(hue<205) key=light>.68?'lightBlue':'blue'; else if(hue<238) key='deepBlue'; else if(hue<265) key='indigo'; else if(hue<305) key='violet'; else key='pink';
  return {key,confidence:clamp(.28+saturation*.55+Math.min(.12,signalRatio*.12),.28,.94)};
}
function analyzeImage(src) { return new Promise(resolve=>{const image=new Image();image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=48;canvas.height=48;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,48,48);const data=ctx.getImageData(0,0,48,48).data;let r=0,g=0,b=0,count=0,total=0;for(let i=0;i<data.length;i+=4){const pr=data[i],pg=data[i+1],pb=data[i+2];total++;const max=Math.max(pr,pg,pb),min=Math.min(pr,pg,pb);const whiteBackground=pr>226&&pg>226&&pb>226&&(max-min)<24;if(whiteBackground)continue;r+=pr;g+=pg;b+=pb;count++;}if(!count){r=245;g=245;b=250;}else{r/=count;g/=count;b/=count;}const light=(r+g+b)/765;const signalRatio=count/total;const photoColor=classifyPhotoColor(r,g,b,signalRatio);let tone='neutro';if(b>r*1.12)tone='azul-violeta';else if(r>g*1.12)tone='cálido';else if(g>r*1.08)tone='verde';state.imageStats={r,g,b,light,tone,auraKey:photoColor.key,auraConfidence:photoColor.confidence,signalRatio};resolve();};image.onerror=resolve;image.src=src;}); }
function stopCamera(){state.stream?.getTracks().forEach(track=>track.stop());state.stream=null;}
function beginAnalysis(){if(state.mode==='aura'&&!state.photo)return toast('Añade una fotografía con fondo blanco para analizar el color visual.');sound();state.screen='analysis';render();log('respuestas_completadas',{mode:state.mode});window.setTimeout(()=>{state.report=createReport();saveReport();state.screen='result';render();sound('reveal');log('lectura_revelada',{mode:state.mode});},2100);}
function renderAnalysis(){layout(`<section class="screen card analysis"><p class="eyebrow">Motor explicable · v${VERSIONS.scoring}</p><h2>Componiendo tu perfil</h2><div class="scan-wrap"><img class="mandala" src="assets/mandala-aura.webp" alt=""><span class="scan-line"></span></div><div class="analysis-steps"><span>Analizando respuestas reportadas</span><span>Calculando coincidencias normalizadas</span><span>Comparando patrones por módulo</span><span>Creando una visualización artística</span></div></section>`);}

function normalizedScores(questions,keys){const scores=Object.fromEntries(keys.map(k=>[k,0]));const max=Object.fromEntries(keys.map(k=>[k,0]));questions.forEach(q=>{keys.forEach(k=>{const weight=q.weights?.[k]||0;if(weight){const contribution=Math.max(0,(state.answers[q.id]||0)-1)/4;scores[k]+=contribution*weight;max[k]+=weight;}});});return Object.fromEntries(keys.map(k=>[k,max[k]?scores[k]/max[k]:0]));}
function rank(scores,meta){return Object.entries(scores).sort((a,b)=>b[1]-a[1]).map(([key,score])=>({key,score,meta:meta[key]}));}
function confidence(score){return Math.round(score*100);}
function auraResult(){const keys=Object.keys(AURA_META);const scores=normalizedScores(auraQuestions,keys);const ranked=rank(scores,AURA_META);const [p,s,t]=ranked;const strong=ranked.filter(x=>x.score>.58);const rainbowScore=keys.filter(k=>['red','orange','yellow','green','pink','blue','violet','gold'].includes(k)).reduce((sum,k)=>sum+scores[k],0)/8;const primary=rainbowScore>.7?'rainbow':p.key;const key=[p.key,s.key].sort().join('|');const combo=AURA_COMBINATIONS[key]||`${AURA_META[p.key].meaning} + ${AURA_META[s.key].meaning}`;const intensity=p.score>.7?'HIGH':p.score>.45?'MODERATE':'LOW';return {primary,primaryScore:primary==='rainbow'?rainbowScore:p.score,secondary:s.key,secondaryScore:s.score,tertiary:t.key,tertiaryScore:t.score,scores,combination:combo,intensity,meta:AURA_META,top:strong.slice(0,4)};}
function soulResult(){const keys=Object.keys(SOUL_META);const scores=normalizedScores(soulQuestions,keys);const ranked=rank(scores,SOUL_META);const p=ranked[0],s=ranked[1];return {primary:p.key,matchScore:p.score,secondary:s.key,secondaryScore:s.score,scores,meta:SOUL_META};}
function starResult(){const keys=Object.keys(STAR_META);const scores=normalizedScores(starQuestions,keys);const ranked=rank(scores,STAR_META);const p=ranked[0],s=ranked[1];const scored=ranked.filter(x=>x.score>.25);return {primary:p.score<.25?'undefined':p.key,matchScore:p.score,secondary:s.score<.25?'undefined':s.key,secondaryScore:s.score,scores,meta:STAR_META,stellarInterest:(state.answers.STAR26||0)>=4,belongingDifference:(state.answers.STAR27||0)>=4,spaceDreamReport:(state.answers.STAR28||0)>=4,defined:scored.length>0};}
function pastResult(soul){const keys=['dejavu','historical','geographic','dreams','relationships','skills','patterns','soulSearch','oldSoul'];const scores=normalizedScores(pastQuestions,keys);const weights={dejavu:.11,historical:.12,geographic:.1,dreams:.12,relationships:.1,skills:.1,patterns:.12,soulSearch:.1,oldSoul:.13};const index=keys.reduce((sum,k)=>sum+scores[k]*weights[k],0);let range='Sin rango';let level='Sin perfil definido';if(index>=.9){range='100+';level='Nivel 6 · Alma Antigua';}else if(index>=.8){range='61–100';level='Nivel 5 · Alma Muy Vieja';}else if(index>=.7){range='31–60';level='Nivel 4 · Alma Vieja';}else if(index>=.55){range='16–30';level='Nivel 3 · Experiencia acumulada';}else if(index>=.4){range='6–15';level='Nivel 2 · Experiencia en desarrollo';}else if(index>=.25){range='1–5';level='Nivel 1 · Experiencia inicial';}const topKey=Object.entries(scores).sort((a,b)=>b[1]-a[1])[0][0];const archetype=PAST_ARCHETYPES[(stableHash(topKey+String(state.answers.PAST09||0))%PAST_ARCHETYPES.length)];return {symbolicIndex:index,range,level,scores,historical:HISTORICAL[state.meta.historical||0],geographic:GEOGRAPHIC[state.meta.geographic||0],archetype,control:scores.control||0,confidence:index,meta:{dejavu:'déjà vu',historical:'afinidad histórica',geographic:'familiaridad geográfica',dreams:'patrones oníricos',relationships:'familiaridad relacional',skills:'habilidades percibidas como naturales',patterns:'patrones recurrentes',soulSearch:'búsqueda de propósito',oldSoul:'orientación existencial'}};}
function createReport(){const aura=auraResult();const soul=soulResult();const past=pastResult(soul);const star=starResult();const p=AURA_META[aura.primary]||AURA_META.violet;const s=AURA_META[aura.secondary];const photoAura=state.mode==='aura'&&state.photo&&state.imageStats.auraKey?{key:state.imageStats.auraKey,score:state.imageStats.auraConfidence,meta:AURA_META[state.imageStats.auraKey]}:null;return {id:Date.now(),mode:state.mode,date:new Date().toLocaleDateString('es',{day:'numeric',month:'long',year:'numeric'}),versions:VERSIONS,answers:{...state.answers},rules:{aura:'normalized_color_score',photoAura:'white_background_chromatic_estimate',soul:'normalized_archetype_match',past:'past_life_symbolic_index',star:'normalized_archetype_affinity'},aura,soul,past,star,photoAura,visualization:{primaryColor:photoAura?.meta?.color||p.color,secondaryColor:s.color,tertiaryColor:AURA_META[aura.tertiary].color,style:'layered_halo',imageTone:state.imageStats.tone,hasPhoto:Boolean(state.photo)},synthesis:`Tu perfil combina asociaciones simbólicas de ${p.label.toLowerCase()} y ${s.label.toLowerCase()}, un arquetipo de ${soul.meta[soul.primary].label.toLowerCase()} y ${star.primary==='undefined'?'un perfil estelar no definido':`afinidad con ${star.meta[star.primary][0]}`}. ${photoAura?`La fotografía aporta el color visual simbólico ${photoAura.meta.label.toLowerCase()}, integrado con tu personalidad y tus sentimientos.`:''} El rango de vidas pasadas pertenece a una convención narrativa independiente; ninguna sección prueba a otra.`,knowledgeVersion:VERSIONS.knowledge};}
function saveReport(){const saved={...state.report,photo:null};const old=JSON.parse(localStorage.getItem('lumina-history')||'[]');const next=[saved,...old.filter(item=>item.id!==saved.id)].slice(0,8);localStorage.setItem('lumina-history',JSON.stringify(next));localStorage.setItem('lumina-last-report',JSON.stringify(saved));state.history=next;}
function loadHistory(){try{state.history=JSON.parse(localStorage.getItem('lumina-history')||'[]');if(!state.history.length){const latest=JSON.parse(localStorage.getItem('lumina-last-report')||'null');if(latest)state.history=[latest];}}catch{state.history=[];}}

function renderResult(){const r=state.report;if(!r){state.screen='welcome';return render();}const p=r.aura.primary==='rainbow'?AURA_META.rainbow:AURA_META[r.aura.primary];const s=AURA_META[r.aura.secondary];const t=AURA_META[r.aura.tertiary];const visual=state.photo?`<img src="${state.photo}" alt="Tu fotografía">`:`<img src="assets/mandala-aura.webp" alt="Mandala artístico" style="transform:none">`;const visualColor=r.visualization?.primaryColor||p.color;const starPrimary=r.star.primary==='undefined'?'Perfil no definido':r.star.meta[r.star.primary][0];const starSecondary=r.star.secondary==='undefined'?'—':r.star.meta[r.star.secondary][0];layout(`<section class="screen report-screen"><div class="result-head"><p class="eyebrow">${r.mode==='aura'?'Aura espiritual':'Tu perfil energético'} · ${r.date}</p><div class="halo-visual" style="--primary:${visualColor};--secondary:${s.color};--tertiary:${t.color}"><div class="halo-particles">✦ · ˚ ✧ · ✦</div><div class="halo-image${state.photo?' has-photo':''}">${visual}</div></div><h2>${p.label}</h2><p class="match-line">Coincidencia con el modelo: <b>${confidence(r.aura.primaryScore)}%</b> · ${r.aura.intensity}</p>${r.photoAura?.meta?.label?`<p class="match-line">Color visual de la fotografía: <b>${r.photoAura.meta.label}</b> · ${confidence(r.photoAura.score)}%</p>`:''}<p class="visual-caption">Visualización artística basada en tu perfil${state.photo?' y en el color general de tu foto':''}.</p></div><div class="report-tabs"><button class="tab active" data-tab="summary">Resumen</button><button class="tab" data-tab="why">¿Por qué?</button><button class="tab" data-tab="details">Detalle</button></div><div id="report-panel">${reportSummary(r,starPrimary,starSecondary)}</div><div class="notice report-notice"><span>✧</span><div><b>Tu lectura espiritual:</b> el color de aura más afín surge de tus respuestas, tu personalidad, tus sentimientos y la tonalidad visible de tu fotografía, combinados en una interpretación simbólica y personal.</div></div><div class="actions"><button class="primary" id="share">Compartir mi perfil</button><button class="secondary" id="again">Nueva lectura</button><button class="secondary" id="delete">Borrar historial local</button></div></section>`);document.querySelectorAll('[data-tab]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');document.querySelector('#report-panel').innerHTML=btn.dataset.tab==='summary'?reportSummary(r,starPrimary,starSecondary):btn.dataset.tab==='why'?reportWhy(r):reportDetails(r);attachReportActions(r);}));attachReportActions(r);}
function reportSummary(r,starPrimary,starSecondary){const p=AURA_META[r.aura.primary]||AURA_META.violet;const s=AURA_META[r.aura.secondary];const t=AURA_META[r.aura.tertiary];const photoTile=r.photoAura?.meta?.label?`<article class="result-tile wide"><small>Color visual de la fotografía</small><strong>${r.photoAura.meta.label}</strong><p>${confidence(r.photoAura.score)}% de afinidad cromática en las zonas no blancas de la imagen, integrada con tus respuestas, personalidad y sentimientos.</p></article>`:'';return `<div class="card report-card"><div class="report-grid"><article class="result-tile"><small>Aura principal</small><strong>${p.label}</strong><p>${confidence(r.aura.primaryScore)}% de coincidencia · ${p.meaning}.</p></article><article class="result-tile"><small>Aura secundaria</small><strong>${s.label}</strong><p>${confidence(r.aura.secondaryScore)}% de coincidencia.</p></article>${photoTile}<article class="result-tile wide"><small>Color terciario · combinación</small><strong>${t.label}</strong><p>${p.label} + ${s.label}: ${r.aura.combination}.</p></article><article class="result-tile"><small>Etapa simbólica del alma</small><strong>${r.soul.meta[r.soul.primary].label}</strong><p>${confidence(r.soul.matchScore)}% de coincidencia con este arquetipo.</p></article><article class="result-tile"><small>Rango narrativo</small><strong>${r.past.range}</strong><p>${r.past.level}. No es una medición histórica.</p></article><article class="result-tile wide"><small>Afinidad estelar</small><strong>${starPrimary}${starSecondary!=='—'?` · ${starSecondary}`:''}</strong><p>Arquetipos simbólicos: no son una raza extraterrestre confirmada.</p></article><article class="result-tile wide"><small>Síntesis</small><p>${r.synthesis}</p></article></div></div>`;}
function reportWhy(r){const auraTop=r.aura.top.length?r.aura.top.map(x=>`<li><b>${x.meta.label}</b> · ${confidence(x.score)}% · respuestas asociadas a ${x.meta.meaning}</li>`).join(''):'<li>No hubo coincidencia alta; se muestra el orden relativo del modelo.</li>';const soulTop=Object.entries(r.soul.scores).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([k,v])=>`<li><b>${r.soul.meta[k].label}</b> · ${confidence(v)}% · ${r.soul.meta[k].description}</li>`).join('');const pastTop=Object.entries(r.past.scores).filter(([k])=>k!=='control').sort((a,b)=>b[1]-a[1]).slice(0,4).map(([k,v])=>`<li><b>${r.past.meta[k]}</b> · ${confidence(v)}%</li>`).join('');const starTop=Object.entries(r.star.scores).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([k,v])=>`<li><b>${r.star.meta[k][0]}</b> · ${confidence(v)}% · afinidad arquetípica</li>`).join('');return `<div class="card explain-card"><p class="eyebrow">Explicabilidad</p><h3>¿Por qué obtuve este resultado?</h3><p class="explain-intro">Cada porcentaje es una coincidencia normalizada con las respuestas 1–5 del cuestionario correspondiente. No representa certeza, probabilidad ni evidencia externa.</p><h4>Aura</h4><ul>${auraTop}</ul><h4>Edad del alma</h4><ul>${soulTop}</ul><h4>Vidas pasadas</h4><ul>${pastTop}</ul><p class="mini-note">El rango se obtuvo con un índice narrativo que pondera déjà vu, afinidades, sueños, patrones y orientación existencial. Las preguntas de control distinguen experiencia subjetiva de afirmación factual.</p><h4>Origen estelar</h4><ul>${starTop}</ul></div>`;}
function reportDetails(r){const p=AURA_META[r.aura.primary]||AURA_META.violet;return `<div class="card explain-card"><p class="eyebrow">Mapa del informe</p><h3>Lectura ampliada</h3><div class="detail-block"><b>Significado de tus colores</b><p>Principal: ${p.meaning}. Secundario: ${AURA_META[r.aura.secondary].meaning}. Terciario: ${AURA_META[r.aura.tertiary].meaning}.</p><p><b>Crecimiento:</b> ${p.growth}.</p><p><b>Asociación tradicional opcional:</b> chakra ${p.chakra}; elemento ${p.element}. Las asociaciones varían entre escuelas y no describen estructuras anatómicas.</p></div><div class="detail-block"><b>Perfil del alma</b><p>${r.soul.meta[r.soul.primary].description}. La categoría secundaria es ${r.soul.meta[r.soul.secondary].label.toLowerCase()}, lo que puede representar tendencias contextuales diferentes, no una contradicción.</p></div><div class="detail-block"><b>Vidas pasadas</b><p>Rango simbólico del modelo: <strong>${r.past.range}</strong>. Afinidad histórica reportada: ${r.past.historical}. Afinidad geográfica reportada: ${r.past.geographic}. Arquetipo narrativo: ${r.past.archetype[1]} (${r.past.archetype[2]}).</p></div><div class="detail-block"><b>Origen estelar</b><p>Principal: ${r.star.primary==='undefined'?'perfil no definido':r.star.meta[r.star.primary][0]}. Secundario: ${r.star.secondary==='undefined'?'no definido':r.star.meta[r.star.secondary][0]}. ${r.star.stellarInterest?'Tu interés estelar fue registrado como preferencia, no puntuado como evidencia.':''}</p></div><div class="version-box">QUESTIONNAIRE ${r.versions.questionnaire} · SCORING ${r.versions.scoring} · INTERPRETATION ${r.versions.interpretation} · RESULT ${r.versions.result} · KNOWLEDGE ${r.versions.knowledge}</div></div>`;}
function attachReportActions(){document.querySelector('#share')?.addEventListener('click',shareReport);document.querySelector('#again')?.addEventListener('click',resetReading);document.querySelector('#delete')?.addEventListener('click',deleteHistory);}
function renderHistory(){state.screen='history';loadHistory();layout(`<section class="screen"><p class="eyebrow">Memoria local</p><h2>Mis resultados</h2><p class="subtitle">Solo se guardan informes sin fotografía en este dispositivo.</p><div class="history-list">${state.history.length?state.history.map((r,i)=>`<button class="history-item" data-history="${i}"><span class="history-orb" style="--orb:${(r.visualization?.primaryColor)||'#b69cff'}"></span><span><b>${AURA_META[r.aura.primary]?.label||'Perfil energético'}</b><small>${r.date} · ${r.past?.range||'lectura guardada'}</small></span><span>→</span></button>`).join(''):'<div class="card"><p class="subtitle">Todavía no tienes lecturas guardadas.</p></div>'}</div><button class="secondary" id="history-back">Volver al inicio</button><button class="secondary danger-button" id="history-delete">Borrar todo el historial</button></section>`);document.querySelectorAll('[data-history]').forEach(btn=>btn.addEventListener('click',()=>{state.report=state.history[Number(btn.dataset.history)];state.photo=null;state.screen='result';sound();render();}));document.querySelector('#history-back').addEventListener('click',()=>{state.screen='welcome';render();});document.querySelector('#history-delete').addEventListener('click',deleteHistory);}
function renderLearn(){state.screen='learn';layout(`<section class="screen card learn-card"><p class="eyebrow">Base de conocimiento · ${VERSIONS.knowledge}</p><h2>Cómo leer este modelo</h2><p>Las tradiciones del aura, los arquetipos de alma, las narrativas Starseed y la reencarnación difieren entre escuelas. Esta experiencia las mantiene separadas y las presenta como lenguaje simbólico.</p>${KNOWLEDGE.map(entry=>`<div class="learn-item"><b>${entry.system}</b><small>${entry.tradition}</small><p>${entry.interpretation}</p><em>${entry.scientific_status}</em></div>`).join('')}<div class="notice"><span>♡</span><div>Esta experiencia no diagnostica salud, personalidad, inteligencia, muerte, criminalidad, posesión ni superioridad espiritual. Tampoco fabrica recuerdos de vidas pasadas.</div></div><button class="secondary" id="learn-back">Volver al inicio</button></section>`);document.querySelector('#learn-back').addEventListener('click',()=>{state.screen='welcome';render();});}
function deleteHistory(){localStorage.removeItem('lumina-history');localStorage.removeItem('lumina-last-report');state.history=[];sound();toast('Historial local eliminado.');if(state.screen==='history')renderHistory();}
async function shareReport(){sound();const r=state.report;const primary=AURA_META[r.aura.primary]?.label||'Arcoíris';const star=r.star.primary==='undefined'?'perfil estelar no definido':r.star.meta[r.star.primary][0];const text=`Mi perfil simbólico en Aura: aura ${primary}, ${r.soul.meta[r.soul.primary].label}, rango narrativo ${r.past.range}, afinidad ${star}. Experiencia espiritual recreativa, no científica.`;try{if(navigator.share)await navigator.share({title:'Mi perfil simbólico · Aura',text});else{await navigator.clipboard.writeText(text);toast('Perfil copiado.');}}catch(error){if(error.name!=='AbortError')toast('No se pudo compartir.');}}
function resetReading(){sound();stopCamera();state.answers={};state.meta={};state.photo=null;state.report=null;state.screen='welcome';render();log('nueva_lectura');}
function toast(message){document.querySelector('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.textContent=message;document.body.appendChild(node);setTimeout(()=>node.remove(),2400);}
function render(){if(state.screen==='welcome')renderWelcome();else if(state.screen==='survey')renderSurvey();else if(state.screen==='context')renderContext();else if(state.screen==='photo')renderPhoto();else if(state.screen==='analysis')renderAnalysis();else if(state.screen==='history')renderHistory();else if(state.screen==='learn')renderLearn();else renderResult();document.querySelector('.app')?.scrollTo(0,0);}
window.addEventListener('pagehide',stopCamera);loadHistory();render();
// Evita que el gesto/botón "atrás" del navegador saque de la app: primero regresa a la pantalla principal de la app.
(function(){
  window.history.pushState({app:true},'',location.href);
  window.addEventListener('popstate',function(){
    window.history.pushState({app:true},'',location.href);
    if(state.screen!=='welcome'){stopCamera?.();state.screen='welcome';render();}
  });
})();
